// Vulnerável: o valor vira parte do texto
await db.query("SELECT id FROM users WHERE email = '" + email + "'");

// Corrigido: o valor viaja como parâmetro
await db.query("SELECT id FROM users WHERE email = $1", [email]);

// Vulnerable: the value becomes part of the text
await db.query("SELECT id FROM users WHERE email = '" + email + "'");

// Fixed: the value travels as a parameter
await db.query("SELECT id FROM users WHERE email = $1", [email]);

const SORTABLE = { price: "price", name: "name" } as const;
const column = SORTABLE[sort as keyof typeof SORTABLE] ?? "name";
await db.query(`SELECT id, name, price FROM products ORDER BY ${column}`);

const SORTABLE = { price: "price", name: "name" } as const;
const column = SORTABLE[sort as keyof typeof SORTABLE] ?? "name";
await db.query(`SELECT id, name, price FROM products ORDER BY ${column}`);

// Vulnerável: um shell interpreta a linha inteira
Bun.spawn(["sh", "-c", `ping -c 1 ${host}`]);

// Corrigido: sem shell, um argumento por posição
Bun.spawn(["ping", "-c", "1", host]);

// Vulnerable: a shell interprets the whole line
Bun.spawn(["sh", "-c", `ping -c 1 ${host}`]);

// Fixed: no shell, one argument per position
Bun.spawn(["ping", "-c", "1", host]);

